'use strict';
const DATA=window.KANJIAN_DATA,$=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const institutions=window.KANJIAN_SOURCE_CATALOG?.institutions||DATA.institutions,materials=DATA.materials,stories=DATA.stories;
let region='all',city='all',query='',toastTimer;
function notify(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,5000)}
function getInstitution(id){return institutions.find(i=>i.id===id)||DATA.institutions.find(i=>i.id===id)}
function getMaterial(id){return materials.find(m=>m.id===id)}
function imageHTML(src,alt,cls=''){return `<img class="${cls}" src="${esc(src)}" alt="${esc(alt)}" width="1536" height="1024" loading="lazy">`}
const shortRegion=name=>name.replace(/省|市|壮族自治区|回族自治区|维吾尔自治区|自治区|特别行政区/g,'');
function regionOptions(selected='all'){return `<option value="all" ${selected==='all'?'selected':''}>全国地区</option>`+window.KANJIAN_MAP.features.filter(f=>typeof f.properties.adcode==='number'&&f.properties.adcode<710000).map(f=>`<option value="${shortRegion(f.properties.name)}" ${selected===shortRegion(f.properties.name)?'selected':''}>${shortRegion(f.properties.name)}</option>`).join('')}
function mapHTML(){const project=p=>[(p[0]-73)*7.3+8,(55-p[1])*8.3+6];let html='';for(const f of window.KANJIAN_MAP.features){const name=shortRegion(f.properties.name),out=typeof f.properties.adcode!=='number'||f.properties.adcode>=710000;const polys=f.geometry.type==='MultiPolygon'?f.geometry.coordinates:[f.geometry.coordinates];let d='';for(const poly of polys)for(const ring of poly)d+=ring.map((p,i)=>{const a=project(p);return(i?'L':'M')+a[0].toFixed(2)+','+a[1].toFixed(2)}).join('')+'Z';html+=`<path d="${d}" class="map-region ${region===name?'selected':''} ${out?'outside':''}" ${out?'':`data-region="${name}" role="button" tabindex="0" aria-label="筛选${name}机构" aria-pressed="${region===name}"`}><title>${esc(f.properties.name||'南海区域示意')}</title></path>`;if(['山东','河南','四川','广东'].includes(name)){const a=project(f.properties.center||f.properties.centroid);html+=`<text class="map-label" x="${a[0]}" y="${a[1]}" text-anchor="middle">${name}</text>`}}return `<svg class="map-svg" viewBox="0 0 470 445" aria-label="全国地区筛选示意，另有省市下拉框" role="group">${html}</svg>`}
function institutionCard(i){if(i.isSource)return sourceInstitutionCard(i);const items=i.materials.map(getMaterial);return `<article class="institution-card"><div class="institution-top"><h2><a href="#institution/${i.id}">${esc(i.name)}</a></h2><span class="meta location">${icon('map-pin')}${i.region} · ${i.city}</span></div><p class="alias muted">曾用名：${esc(i.alias)}</p><div class="media-strip"><a href="#institution/${i.id}" aria-label="${i.name}档案">${imageHTML('assets/campus.webp','AI 生成校园示意，非真实机构照片')}<span class="media-label">${icon('building-2')}机构示意</span></a><a href="#material/${items[0].id}">${imageHTML(items[0].image,'AI 生成资料示意')}<span class="media-label">${kindIcon(items[0].kind)}${items[0].kind}</span></a><a href="#material/${items.at(-1).id}">${imageHTML(items.at(-1).image,'AI 生成关联资料示意')}<span class="media-label">${kindIcon(items.at(-1).kind)}${items.at(-1).kind==='视频'?'播放 · 00:08':'资料示意'}</span></a></div><p class="card-summary">${esc(i.summary)}</p><div class="card-links"><a href="#institution/${i.id}">${i.materials.length} 份资料${i.stories.length?' · '+i.stories.length+' 段经历':''}</a><button class="quiet" data-share="institution/${i.id}">${icon('share-2')}分享与保存</button></div></article>`}
function cityOptions(){return '<option value="all">全部城市</option>'+[...new Set(institutions.filter(i=>region==='all'||i.region===region).map(i=>i.city))].map(c=>`<option ${c===city?'selected':''}>${c}</option>`).join('')}
function renderResults(){const rows=institutions.filter(i=>(region==='all'||i.region===region)&&(city==='all'||i.city===city)&&(!query||[i.id,i.name,i.alias,i.region,i.city].join(' ').toLowerCase().includes(query.toLowerCase())));$('results-heading').textContent=(region==='all'?'全国':region)+(city==='all'?'':' · '+city)+'来源目录';$('results-count').textContent=rows.length+' 份来源记录';$('institution-list').innerHTML=rows.length?rows.slice(0,sourceLimit).map(institutionCard).join('')+(rows.length>sourceLimit?'<button id="source-more" class="spaced">继续显示机构记录</button>':''):`<div class="empty"><h3>没有匹配的来源记录</h3><p>空白地区不代表不存在相关机构。</p><button data-reset>查看全部目录</button></div>`;archiveHydrate('home');}
function renderHome(){return `<div class="page-title"><p class="eyebrow">戒网瘾 · 特训 · 封闭矫正</p><h1>查找机构与相关资料</h1><p class="catalog-intro">1251份来源记录，保留出处与核对状态。一起留下资料，也支持经历这些的人。</p><form class="search-bar" id="institution-search"><input id="institution-query" type="search" value="${esc(query)}" placeholder="机构名称、曾用名或城市" aria-label="查找机构"><button class="primary" type="submit">${icon('search')}查找</button></form></div><div class="home-layout"><aside class="map-panel"><div class="map-title"><h2 class="icon-heading">${icon('map-pin')}按地区查看</h2><button class="quiet" data-reset>返回全国</button></div><details class="mobile-map"><summary>展开全国地区图</summary><div id="map">${mapHTML()}</div></details><div class="region-select"><label>省级地区<select id="province">${regionOptions(region)}</select></label><label>城市<select id="city">${cityOptions()}</select></label></div><p class="map-key">地区筛选 · DataV底图示意；目录地区未经逐项核实。服务范围：中国大陆</p></aside><section><div class="heading-line section-head"><h2 id="results-heading"></h2><span class="muted" id="results-count" role="status"></span></div><div id="live-institutions"></div><div id="institution-list"></div><div class="soft-note"><h3>资料与经历，可以慢慢补充</h3><p>每份材料保留自己的出处。缺少的部分先留下说明，已有的记录也可以更正。</p><a class="quiet button" href="#provide">${icon('folder-open')}整理一份资料</a></div></section></div>`}
document.addEventListener('input',e=>{if(e.target.id==='institution-query'){sourceLimit=30;query=e.target.value;renderResults()}});
document.addEventListener('submit',e=>{if(e.target.id==='institution-search'){e.preventDefault();query=$('institution-query').value;renderResults()}});
function updateRegion(value){sourceLimit=30;region=value;city='all';$('province').value=region;$('city').innerHTML=cityOptions();$('map').innerHTML=mapHTML();renderResults()}
document.addEventListener('change',e=>{if(e.target.id==='province')updateRegion(e.target.value);if(e.target.id==='city'){city=e.target.value;renderResults()}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-region]');if(b)updateRegion(b.dataset.region);if(e.target.closest('[data-reset]')){query='';$('institution-query').value='';updateRegion('all')}});
document.addEventListener('keydown',e=>{const b=e.target.closest('[data-region]');if(b&&['Enter',' '].includes(e.key)){e.preventDefault();updateRegion(b.dataset.region)}});

